let rev = qa.frame(Some(comp.clone()), 0.3);
let d = mean_diff(&qa.frame(Some(pre["comp"].clone()), 1.6), &rev);
let mut rival = f64::MAX;
let mut t = 0.0f64;
while t <= 1.9 + 1e-9 {
    if (t - 1.6).abs() > 0.1 {
        rival = rival.min(mean_diff(&qa.frame(Some(pre["comp"].clone()), t), &rev));
    }
    t += 0.1;
}
